    		const cssNextErrors = 'font-size:small;text-align:left;display:none;';
    		const cssMoreErrorButton = 'font-size:medium;padding:0.3em;margin:0.2em;text-decoration: underline;';

    		dlg.html = `<style>div.mainError {${cssFirstError} } div.nextError {${cssNextErrors}}</style>`;

    		window.showNextErrors90731596 = function() { 
    			$('.nextError').slideDown(); 
    		};

    		for (var i = 0; i < hintErrors.length; ++i) {
    			ntf.logger.info('  hintError #' + i);
    			var err = hintErrors[i];
    			if (!err) continue;

    			ntf.logger.info(JSON.stringify(err));

    			var faultLine = err.evidence?.trim() || '';
    			// Tweak error if await used out of async
    			if (err.reason.includes('Missing semicolon') && err.evidence.includes('await') ) {
    				err.reason = 'Await used out of async function';
    			}
    			faultLine = main.htmlEncode(faultLine);

    			dlg.html += `<div class='${i===0 ? 'mainError' : 'nextError'}' style='${i===0 ? cssFirstError : cssNextErrors}'>
    					${err.reason} | Line ${err.line || 'n/a'}<br/>
    					${err.evidence?.includes('await') ? '( Check if <i>await</i> is used out of <i>async</i> context )<br/>' : ''}
    					<div style='margin:.3em;padding:.3em;background-color:#EEE;text-align:left;font-family:Monospace'>
    					${faultLine || 'n/a'}
    					</div></div>`;
    					//<hr/>`;
    			if (i===0 && hintErrors.length > 1) {
    				dlg.html += `<a style="${cssMoreErrorButton}" onclick="showNextErrors90731596();">More errors</a>`;
    			}

    			ntf.logger.error( `${err.reason} | "${err.evidence || 'n/a'}" | Line ${err.line || 'n/a'}`); 
    			msg += `${err.reason} | Line ${err.line || 'n/a'}<hr/>`;

    		}				

    		if (ntf.context.fieldChanged) {
				ft3.ModalService.openModal(dlg)
				.then(
					function confirmF() { resolve(true); },
					function cancelF() { resolve(true); }
				);
    		}
    		else {
    			dlg.showCancelButton = true;
    			dlg.confirmButtonText = 'Save Anyway';

				ft3.ModalService.openModal(dlg)
				.then(
					function confirmF() {
						resolve(true);
					}	,
					function cancelF() {
						resolve(false);
					}
				);
    		}        
        });
    }
}
